    row_bounds = [-1] + row_lines + [h]
    col_bounds = [-1] + col_lines + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    marks = {}
    for i, (r0, r1) in enumerate(row_spans):
        for j, (c0, c1) in enumerate(col_spans):
            vals = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1)} - {0, 8}
            if vals:
                marks[i, j] = next(iter(vals))
    covered = {color: set() for color in marks.values()}
    for color in covered:
        pts = [p for p, v in marks.items() if v == color]
        for i in {i for i, j in pts}:
            js = [j for x, j in pts if x == i]
            covered[color].update((i, j) for j in range(min(js), max(js) + 1))
        for j in {j for i, j in pts}:
